+// In-memory notes store keyed by note id.
+const notes = new Map();
+let nextId = 0;
+
+function makeId() {
+  nextId += 1;
+  return `n${nextId}`;
+}
+
+function requireNonEmptyString(value, paramName, toolName) {
+  if (typeof value !== 'string' || value.trim() === '') {
+    throw new Error(
+      `${toolName}: parameter "${paramName}" must be a non-empty string`
+    );
+  }
+  return value;
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'note_create',
+      description:
+        'Create a new note with a non-empty title and body. Returns the created note as structured JSON text, including a stable generated id.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          title: {
+            type: 'string',
+            description: 'Title of the note. Must be a non-empty string.',
+            minLength: 1,
+          },
+          body: {
+            type: 'string',
+            description: 'Body content of the note. Must be a non-empty string.',
+            minLength: 1,
+          },
+        },
+        required: ['title', 'body'],
+        additionalProperties: false,
+      },
+      annotations: {
+        readOnlyHint: false,
+        destructiveHint: false,
+        idempotentHint: false,
+        openWorldHint: false,
+      },
+    },
+    {
+      name: 'note_get',
+      description:
+        'Retrieve a single note by its id. Returns the note as structured JSON text. Rejects unknown note ids.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          note_id: {
+            type: 'string',
+            description: 'The id of the note to retrieve (e.g. "n1").',
+            minLength: 1,
+          },
+        },
+        required: ['note_id'],
+        additionalProperties: false,
+      },
+      annotations: {
+        readOnlyHint: true,
+        destructiveHint: false,
+        idempotentHint: true,
+        openWorldHint: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args) {
+  const arguments_ = args || {};
+
+  if (name === 'note_create') {
+    const title = requireNonEmptyString(arguments_.title, 'title', 'note_create');
+    const body = requireNonEmptyString(arguments_.body, 'body', 'note_create');
+    const id = makeId();
+    const note = { id, title, body };
+    notes.set(id, note);
+    return {
+      content: [{ type: 'text', text: JSON.stringify(note) }],
+    };
+  }
+
+  if (name === 'note_get') {
+    const noteId = requireNonEmptyString(
+      arguments_.note_id,
+      'note_id',
+      'note_get'
+    );
+    const note = notes.get(noteId);
+    if (!note) {
+      throw new Error(`note_get: no note found with id "${noteId}"`);
+    }
+    return {
+      content: [{ type: 'text', text: JSON.stringify(note) }],
+    };
+  }
+
+  throw new Error(
+    `Unknown tool: "${name}". Available tools: note_create, note_get.`
+  );
+}
